            if (listCustomerCommitsV1Request.EffectiveBeforeOption.IsSet)
                writer.WriteString("effective_before", listCustomerCommitsV1Request.EffectiveBeforeOption.Value!.Value.ToString(EffectiveBeforeFormat));

            if (listCustomerCommitsV1Request.IncludeContractCommitsOption.IsSet)
                writer.WriteBoolean("include_contract_commits", listCustomerCommitsV1Request.IncludeContractCommitsOption.Value!.Value);

            if (listCustomerCommitsV1Request.IncludeArchivedOption.IsSet)
                writer.WriteBoolean("include_archived", listCustomerCommitsV1Request.IncludeArchivedOption.Value!.Value);

            if (listCustomerCommitsV1Request.IncludeLedgersOption.IsSet)
                writer.WriteBoolean("include_ledgers", listCustomerCommitsV1Request.IncludeLedgersOption.Value!.Value);

            if (listCustomerCommitsV1Request.IncludeBalanceOption.IsSet)
                writer.WriteBoolean("include_balance", listCustomerCommitsV1Request.IncludeBalanceOption.Value!.Value);

            if (listCustomerCommitsV1Request.NextPageOption.IsSet)
                writer.WriteString("next_page", listCustomerCommitsV1Request.NextPage);

            if (listCustomerCommitsV1Request.LimitOption.IsSet)
                writer.WriteNumber("limit", listCustomerCommitsV1Request.LimitOption.Value!.Value);
        }
    }
}
